package com.hesi.snotes

import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.Base64

/**
 * GENERATED FILE - weights of the shape detector's neural network.
 *
 * A multilayer perceptron (38 -> 128 -> 64 -> 11, ReLU hidden layers, softmax over 11 classes)
 * trained offline with scikit-learn on 156,000 synthetic hand-drawn strokes (see
 * tools/shape-model/ in the project). Features are standardised with the
 * training mean/std below. Inference is ~13760 multiply-adds - well under a
 * millisecond on a phone.
 */
object ShapeModel {
    private const val MU = "ZM3IPqpljj57/lw9AzmYPk2XEz/ulaY+WCa4P1X/bz97Kyo/+g45P+iEUT8TwBg/SPKAPsgnMj+y7io+h8VaP+r3pkACxuk9EYwKPrAhFT8fzFA/UhlqP8qAcz/iBXA/ciSuPrXGi0Dp5kw81GqyPtbdlD9Cdws/7K7XPQeWBT47sRM+Z06RPvK6CD6IiU8+Tc4LP5XgGD0="
    private const val SD = "FbHVPl/TsD5IklI98/KjPvggoz6aXSs+6+x1P4jBQz9LsIs+5kv3PZZOlD5bOqY+nW2OPgM8JD92YQQ+fWoIPxibIUAVp5s+KJaYPidJLz7L2fg9iF6mPWr7YD37xf0/KetLP6DgNUDDmCU8b4JyPuSFyj6K+P4+kCmdPoJxrD6v4LM+tdTmPhYnrj7B0c0+VPizPkfw8zw="
    private const val W0 = "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            ""
    private const val B0 = ""
    private const val W1 = "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            ""
    private const val B1 = ""
    private const val W2 = ""
    private const val B2 = "ShPIPvWicr5AG9e+b8XwvgXg0T20m3C+VFEVvZhNMr6B402/dvKsvQ51Zz4="

    private fun floats(b64: String): FloatArray {
        val bytes = Base64.getDecoder().decode(b64)
        val fb = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer()
        return FloatArray(fb.remaining()).also { fb.get(it) }
    }

    private val dims = arrayOf(intArrayOf(38, 128), intArrayOf(128, 64), intArrayOf(64, 11))
    private val mu by lazy { floats(MU) }
    private val sd by lazy { floats(SD) }
    private val weights by lazy { arrayOf(floats(W0), floats(W1), floats(W2)) }
    private val biases by lazy { arrayOf(floats(B0), floats(B1), floats(B2)) }

    /** Class probabilities (ShapeRecognizer.Kind order) for a feature vector. */
    fun predict(features: FloatArray): FloatArray {
        var x = FloatArray(features.size) { (features[it] - mu[it]) / sd[it] }
        for (l in dims.indices) {
            val nIn = dims[l][0]; val nOut = dims[l][1]
            val w = weights[l]; val b = biases[l]
            val y = FloatArray(nOut)
            for (o in 0 until nOut) {
                var s = b[o]
                // scikit-learn stores coefs as [in][out] (row-major)
                for (i in 0 until nIn) s += x[i] * w[i * nOut + o]
                y[o] = if (l < dims.size - 1) (if (s > 0f) s else 0f) else s
            }
            x = y
        }
        // softmax
        var m = x[0]
        for (v in x) if (v > m) m = v
        var sum = 0f
        for (i in x.indices) { x[i] = kotlin.math.exp(x[i] - m); sum += x[i] }
        for (i in x.indices) x[i] /= sum
        return x
    }
}
